#!/usr/bin/env bash\n# Test for Nightly Commit Emoji Annotator\n# Mock rationale: we set GIT_LOG_MOCK to avoid calling real git.\n\nset -euo pipefail\n\n# Mock commit messages (newline separated)\nexport GIT_LOG_MOCK=$'Fix bug in parser\nAdd new feature\nUpdate docs'\n\n# Run the script\noutput=$(bash src/main.sh 3)\n\nexpected=$'🛠️ Fix bug in parser\n➕ Add new feature\n📚 Update docs'\n\nif [[ \"$output\" == \"$expected\" ]]; then\n  echo "PASS"\nelse\n  echo "FAIL"\n  echo "Expected:"\n  echo "$expected"\n  echo "Got:"\n  echo "$output"\n  exit 1\nfi\n
